import{_ as t,o as e,c as s,ag as n}from"./chunks/framework.C5oN-8Wt.js";const r="/cns_master_docs/teaching-v0.2.0-alpha/01-link-overview.svg",u=JSON.parse('{"title":"01 无人机状态回传的链路全貌","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/learn/01-link-overview/index.md","filePath":"v0.2.0-alpha/learn/01-link-overview/index.md"}'),i={name:"v0.2.0-alpha/learn/01-link-overview/index.md"};function l(o,a,p,d,h,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="_01-无人机状态回传的链路全貌" tabindex="-1">01 无人机状态回传的链路全貌 <a class="header-anchor" href="#_01-无人机状态回传的链路全貌" aria-label="Permalink to &quot;01 无人机状态回传的链路全貌&quot;">​</a></h1><p>适用 <strong>v0.2.0-alpha</strong>。本课先读链路图，再选做一个 PC 信号处理热身。</p><h2 id="低空应用问题" tabindex="-1">低空应用问题 <a class="header-anchor" href="#低空应用问题" aria-label="Permalink to &quot;低空应用问题&quot;">​</a></h2><p>地面站显示“高度 30 m”，是不是传感器把一个“30”直接送进了屏幕？设想无人机正在巡检：测量、组织数据、传输、接收解释、显示，任一步不同，屏幕上的数值含义都可能改变。先知道各环节在做什么，后面才知道仿真信号位于哪里。</p><h2 id="学习目标与前置知识" tabindex="-1">学习目标与前置知识 <a class="header-anchor" href="#学习目标与前置知识" aria-label="Permalink to &quot;学习目标与前置知识&quot;">​</a></h2><p>完成本课后，你能指出数据内容、信号表示、承载链路和显示的区别，并运行最简单的处理分支。只需要会读“横轴时间、纵轴数值”，不要求通信知识。</p><p>“遥测”就是把远处设备测得或报告的状态送回来；“报文”是按约定格式组织的一段数据；“协议”是两端约定的数据格式和交互规则。</p><h2 id="一条可能的链路" tabindex="-1">一条可能的链路 <a class="header-anchor" href="#一条可能的链路" aria-label="Permalink to &quot;一条可能的链路&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>无人机上的传感器／定位接收机</span></span>
<span class="line"><span>          ↓ 测量或解算结果：高度、速度、经纬度等</span></span>
<span class="line"><span>飞控／机载计算机</span></span>
<span class="line"><span>          ↓ 按协议组织报文</span></span>
<span class="line"><span>通信设备：把数据转换成适合传输的信号</span></span>
<span class="line"><span>          ↓ 电台空口，或蜂窝等网络（具体架构不同）</span></span>
<span class="line"><span>地面接收设备／网络接口</span></span>
<span class="line"><span>          ↓ 恢复数据并按协议解释</span></span>
<span class="line"><span>地面站：检查来源、单位、时间和状态，再显示</span></span></code></pre></div><p>例如经纬度已经是定位接收机输出的结果。传输这些数字不等于完成卫星测距或定位解算；通信链路把一条位置消息送回来，也不保证该位置准确或仍然及时。</p><p>后续实验主要放大观察中间的<strong>信号表示与处理</strong>。本组不产生真实高度报文、不模拟完整蜂窝网络，也不连接电台。QGC 的真实飞控连接属于另一条操作路径，不是做这些实验的前提。</p><h2 id="可选热身-让一个数经过处理再观察" tabindex="-1">可选热身：让一个数经过处理再观察 <a class="header-anchor" href="#可选热身-让一个数经过处理再观察" aria-label="Permalink to &quot;可选热身：让一个数经过处理再观察&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.2.0-alpha/01-link-overview.cnsproj" download>下载 01-link-overview.cnsproj</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1 out ──→ 增益器 1 in → out</span></span>
<span class="line"><span>     └──────── 观察处理前      └── 观察处理后</span></span></code></pre></div><p>这个小图只表示软件中的信号处理，不把它的节点逐一冒称为传感器、电台和地面站。</p><table tabindex="0"><thead><tr><th>设置</th><th>值与理由</th></tr></thead><tbody><tr><td>信号源波形／幅度／频率</td><td>正弦、1、64 Hz；提供容易辨认的重复变化，幅度为归一化值。</td></tr><tr><td>信号源采样率</td><td>1024 sample/s；每周期 16 点，方便数点和读图。</td></tr><tr><td>增益</td><td>1；先让输出与输入一致，建立“处理前后”的参照。</td></tr></tbody></table><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>用 Master 的“文件 → 打开工程”载入下载文件。完整通用操作见<a href="./../#第一次操作先看这里">学习路径</a>。</li><li>在观察器“参数”页核对信号源与增益输出。若只有一路，点击“添加捕获变量”，确认另一路 <code>out</code>；模式选时域叠加。两路同为归一化幅度，可以共用纵轴。</li><li>将每路样本数设为 <strong>4096</strong>，按 <strong>F5</strong>。在输出页点“自动刻度”，再把横轴缩到约 <strong>0.0625 s</strong>，这段应有四个周期。</li><li>停止后读输入和输出。增益为 1 时两路应重合；重合可能遮住其中一种颜色，先看图例再判断是否缺数据。</li><li>完成下面的单参数对照，用“另存为”保存自己的工程。下课前按 <strong>Shift+F5</strong>。</li></ol><h2 id="预期图像及解释" tabindex="-1">预期图像及解释 <a class="header-anchor" href="#预期图像及解释" aria-label="Permalink to &quot;预期图像及解释&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.2.0-alpha/01-link-overview.svg"><img src="`+r+'" alt="实际 GNU 数据：增益为 1 时两路重合，改为 2 后输出幅度翻倍"></a></p><p>参考图取自本课工程每路 2048 样本的实际 GNU 运行，右图为只改增益的对照；它不是 Master 截图。以下各课同样使用真实计算的静态参考图，窗口样式以你运行的 Master 为准。</p><p>时域中两路围绕 0 重复起伏，峰值约 +1、谷值约 −1，周期约 <strong>0.015625 s</strong>。增益 1 的意思是每个输入值乘 1，因此两路逐点相同。这里的纵轴不是高度 m；不能从幅度 1 推出“无人机高度 1 m”。</p><h2 id="单参数对照" tabindex="-1">单参数对照 <a class="header-anchor" href="#单参数对照" aria-label="Permalink to &quot;单参数对照&quot;">​</a></h2><p>先预测：增益从 <strong>1 改为 2</strong>，周期会改变吗？停止、只改增益、重新运行。输出峰谷应变为约 ±2，输入仍约 ±1，周期不变。自动纵轴可能把两次运行分别铺满窗口，务必读刻度，或在同一观察器叠加输入／输出比较。</p><p>写下：本次改变的是大小、快慢，还是消息内容？答案应指向<strong>样本数值的大小</strong>。这个实验不能证明无线通信距离或功率增益。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查</th></tr></thead><tbody><tr><td>打开工程仍空白</td><td>是否只按了 Ctrl+F5？用 F5 启动实际计算。</td></tr><tr><td>只见一条线</td><td>看图例和绑定；完全重合时一条会遮住另一条。</td></tr><tr><td>改增益后看起来一样高</td><td>自动刻度可能改变了纵轴，读数值刻度或叠加两路。</td></tr><tr><td>另一课运行不了</td><td>当前任务可能还在运行，先 Shift+F5，再打开下一课。</td></tr></tbody></table><p><a href="./../../modules/signal_source/">查信号源</a> · <a href="./../../modules/gain/">查增益</a> · <a href="./../02-wave-quantities/">下一课：幅度、频率与相位 →</a></p>',28)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
